mapper.select:
select u1.u_name as uName, c.c_name as cName, mn.* from Contract_Permission_User mn left join Sys_User u1 on u1.u_id=mn.u_id left join SYS_Company c on u1.c_Id=c.C_Id
and mn.con_id=#{params.conId}
and INSTR(u1.u_name,#{params.uName})
and likeCname(#{params.cName},c.C_Id)=true
and INSTR(c.c_name,#{params.cName})
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.cpu_sort asc
